SELECT (SELECT value FROM public.settings WHERE key='active_batch') AS active_batch,(SELECT count(*) FROM public.entries WHERE batch_id='directory-additions-20261027') AS entries,(SELECT count(*) FROM public.offers WHERE batch_id='directory-additions-20261027') AS offers,(SELECT count(*) FROM public.entries e JOIN public.entries o ON o.batch_id='directory-additions-20261018' AND o.entry_key=e.entry_key WHERE e.batch_id='directory-additions-20261027' AND (e.payload<>o.payload OR e.content_hash<>o.content_hash)) AS changed_existing,(SELECT count(*) FROM ((SELECT id,entry_key,amount_cents,max_cents,price_type,payload FROM public.offers WHERE batch_id='directory-additions-20261018') EXCEPT (SELECT id,entry_key,amount_cents,max_cents,price_type,payload FROM public.offers WHERE batch_id='directory-additions-20261027')) d) AS missing_or_changed_offers;
